<script setup>
import { computed, ref } from 'vue'
import { addDays, shiftName, today } from '../services/api'
const props=defineProps({entries:{type:Array,default:()=>[]},nurses:{type:Array,default:()=>[]},start:String,editable:Boolean,leaders:{type:Object,default:null},duration:{type:Number,default:7},editableStart:String,editableEnd:String})
const emit=defineEmits(['edit']); const search=ref(''), view=ref('group')
const days=computed(()=>Array.from({length:props.duration===14?14:7},(_,i)=>addDays(props.start,i)))
const entries=computed(()=>Object.fromEntries(props.entries.map(e=>[e.nurse+'|'+e.date,e])))
const rows=computed(()=>props.nurses.filter(n=>n.name.includes(search.value)||n.employee_id?.includes(search.value)).slice().sort((a,b)=>view.value==='group'?((a.base_type==='day'?5:a.subgroup)-(b.base_type==='day'?5:b.subgroup)):a.name.localeCompare(b.name)))
const codes=computed(()=>Array.from(new Set(['A','DAY','N','POST','OFF',...props.entries.map(e=>e.shift)])))
const entry=(n,d)=>entries.value[n.id+'|'+d]
const count=(code,d)=>props.entries.filter(e=>e.date===d&&e.shift===code).length
const canEdit=day=>props.editable&&(!props.editableStart||day>=props.editableStart)&&(!props.editableEnd||day<=props.editableEnd)
const role=n=>n.subgroup==null?'未分组':props.leaders==null?(n.is_leader?'具备带组资格':'组员'):
  n.is_leader&&String(props.leaders[String(n.subgroup)])===String(n.id)?'带组老师':'组员'
</script>
<template><div class="matrix-tools"><el-radio-group v-model="view" size="small"><el-radio-button value="group">小组视图</el-radio-button><el-radio-button value="person">人员视图</el-radio-button></el-radio-group><el-input v-model="search" clearable placeholder="搜索姓名或工号" style="width:220px"/></div><div class="table-scroll"><table :class="['schedule-matrix',{'two-weeks':duration===14}]"><thead><tr v-if="duration===14" class="week-labels"><th colspan="4"></th><th colspan="7">第1周</th><th colspan="7">第2周</th></tr><tr><th>所属小组</th><th>护士姓名</th><th>层级</th><th>岗位 / 角色</th><th v-for="(day,i) in days" :key="day" :class="{today:day===today(),'week-start':i===7}">{{day.slice(5)}}<small>{{day===today()?'今天':['周日','周一','周二','周三','周四','周五','周六'][new Date(day+'T12:00:00').getDay()]}}</small></th></tr></thead><tbody><tr v-for="n in rows" :key="n.id"><td>{{n.base_type==='day'?'长期白班':n.subgroup?`第${n.subgroup}小组`:'待分组'}}</td><td class="name-cell"><span class="avatar tiny">{{n.name.slice(-1)}}</span>{{n.name}}</td><td>{{n.level}}</td><td>{{role(n)}}</td><td v-for="(day,i) in days" :key="day" :class="['shift-cell','shift-'+entry(n,day)?.shift,{today:day===today(),clickable:canEdit(day),'week-start':i===7}]" @click="canEdit(day)&&emit('edit',{nurse:n.id,date:day,...entry(n,day)})"><button v-if="canEdit(day)" class="cell-button" :aria-label="n.name+' '+day+' 编辑班次'">{{shiftName(entry(n,day)?.shift)}}</button><span v-else>{{shiftName(entry(n,day)?.shift)}}</span><sup v-if="entry(n,day)?.source==='approved_request'" title="已批准并应用的申请">申</sup><sup v-if="entry(n,day)?.source==='manager_edit'" :title="entry(n,day)?.reason">调</sup></td></tr><tr v-if="!rows.length"><td :colspan="4+days.length" class="empty-cell">暂无排班数据，请先生成排班。</td></tr></tbody><tfoot><tr v-for="code in codes" :key="code"><th colspan="4">{{shiftName(code)}}人数</th><td v-for="(day,i) in days" :key="day" :class="{today:day===today(),'week-start':i===7}">{{count(code,day)}}</td></tr></tfoot></table></div></template>
<style scoped>
.two-weeks{width:max-content;min-width:0;table-layout:auto}.two-weeks .week-start{border-left:2px solid #b3d6f8}.two-weeks thead tr:not(.week-labels) th:nth-child(-n+4),.two-weeks tbody td:nth-child(-n+4){position:sticky;background:#fff;z-index:2;white-space:nowrap}.two-weeks thead tr:not(.week-labels) th:nth-child(-n+4){background:#eaf5ff;z-index:3}.two-weeks :is(thead tr:not(.week-labels),tbody tr)>:nth-child(1){left:0;width:85px;min-width:85px;max-width:85px}.two-weeks :is(thead tr:not(.week-labels),tbody tr)>:nth-child(2){left:85px;width:100px;min-width:100px;max-width:100px}.two-weeks :is(thead tr:not(.week-labels),tbody tr)>:nth-child(3){left:185px;width:65px;min-width:65px;max-width:65px}.two-weeks :is(thead tr:not(.week-labels),tbody tr)>:nth-child(4){left:250px;width:95px;min-width:95px;max-width:95px}.two-weeks thead tr:not(.week-labels)>:nth-child(n+5),.two-weeks tbody tr>:nth-child(n+5),.two-weeks tfoot td{width:72px;min-width:72px;white-space:nowrap}.two-weeks .week-labels th:first-child,.two-weeks tfoot th{position:sticky;left:0;z-index:3;background:#eaf5ff}.two-weeks .week-labels th:last-child{border-left:2px solid #b3d6f8}
</style>
